testsCode:
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { buscarPorId } from './solution.mjs';

const usuarios = [
  { id: 1, nome: 'Ana' },
  { id: 2, nome: 'Bia' },
  { id: 3, nome: 'Caio' },
];

test('id existente: 200 com o recurso em JSON', () => {
  assert.deepEqual(buscarPorId(usuarios, 2), { statusCode: 200, body: '{"id":2,"nome":"Bia"}' });
});

test('limite: busca o último item da lista', () => {
  assert.deepEqual(buscarPorId(usuarios, 3), { statusCode: 200, body: '{"id":3,"nome":"Caio"}' });
});

test('id inexistente: 404 com erro em JSON', () => {
  assert.deepEqual(buscarPorId(usuarios, 99), { statusCode: 404, body: '{"erro":"recurso não encontrado"}' });
});

test('limite: lista vazia devolve 404', () => {
  assert.deepEqual(buscarPorId([], 1), { statusCode: 404, body: '{"erro":"recurso não encontrado"}' });
});

solutionCode:
export function buscarPorId(recursos, id) {
  if (!Array.isArray(recursos)) {
    throw new Error('lista de recursos inválida');
  }

  const encontrado = recursos.find((r) => r.id === id);
  if (encontrado === undefined) {
    return { statusCode: 404, body: JSON.stringify({ erro: 'recurso não encontrado' }) };
  }

  return { statusCode: 200, body: JSON.stringify(encontrado) };
}
